def solution(keys, changes, threshold):
    totals = {}
    arrived = set()
    answer = []
    for key, change in zip(keys, changes):
        totals[key] = totals.get(key, 0) + change
        if key not in arrived and totals[key] >= threshold:
            arrived.add(key)
            answer.append(key)
    return answer

def solution(commands, capacity):
    owned = {}
    remaining = capacity
    answer = []
    for command in commands:
        action, name, raw_amount = command.split()
        amount = int(raw_amount)
        if action == 'reserve':
            if amount <= remaining:
                remaining -= amount
                owned[name] = owned.get(name, 0) + amount
        elif owned.get(name, 0) >= amount:
            owned[name] -= amount
            remaining += amount
        answer.append(remaining)
    return answer

def solution(sources, maxSources):
    counts = {}
    left = 0
    best = 0
    for right, source in enumerate(sources):
        counts[source] = counts.get(source, 0) + 1
        while len(counts) > maxSources:
            outgoing = sources[left]
            counts[outgoing] -= 1
            if counts[outgoing] == 0:
                del counts[outgoing]
            left += 1
        best = max(best, right - left + 1)
    return best
